Here's a debounced search in plain JavaScript and in React. Both also cancel in-flight requests, so a slow, stale response can't overwrite a newer one.

## Vanilla JavaScript

```html
<input id="search" type="search" placeholder="Search..." />
<ul id="results"></ul>
```

```js
function debounce(fn, delay = 300) {
  let timerId;
  const debounced = (...args) => {
    clearTimeout(timerId);
    timerId = setTimeout(() => fn(...args), delay);
  };
  debounced.cancel = () => clearTimeout(timerId);
  return debounced;
}

const input = document.getElementById('search');
const resultsEl = document.getElementById('results');
let controller; // AbortController for the in-flight request

async function search(query) {
  controller?.abort();               // cancel the previous request
  if (!query.trim()) {
    resultsEl.innerHTML = '';
    return;
  }

  controller = new AbortController();
  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
      signal: controller.signal,
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    resultsEl.innerHTML = data.results
      .map((r) => `<li>${escapeHtml(r.name)}</li>`)
      .join('');
  } catch (err) {
    if (err.name !== 'AbortError') console.error('Search failed:', err);
  }
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}

const debouncedSearch = debounce(search, 300);
input.addEventListener('input', (e) => debouncedSearch(e.target.value));
```

## React (hooks)

```jsx
import { useEffect, useState } from 'react';

function useDebouncedValue(value, delay = 300) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id); // reset timer on every keystroke
  }, [value, delay]);
  return debounced;
}

export default function SearchBox() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const debouncedQuery = useDebouncedValue(query, 300);

  useEffect(() => {
    if (!debouncedQuery.trim()) {
      setResults([]);
      return;
    }

    const controller = new AbortController();
    setLoading(true);

    fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then((data) => setResults(data.results))
      .catch((err) => {
        if (err.name !== 'AbortError') console.error('Search failed:', err);
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false);
      });

    return () => controller.abort(); // cancel when the query changes or on unmount
  }, [debouncedQuery]);

  return (
    <div>
      <input
        type="search"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search..."
      />
      {loading && <p>Loading…</p>}
      <ul>
        {results.map((r) => (
          <li key={r.id}>{r.name}</li>
        ))}
      </ul>
    </div>
  );
}
```

## How it works

- **Debounce:** Each keystroke resets a timer. The API call only fires once the user has stopped typing for `delay` ms. Typing "react" quickly sends 1 request instead of 5.
- **AbortController:** Debouncing alone doesn't stop races. If request A is slow and request B is fast, A could finish last and show stale results. Aborting the previous request prevents that.
- **Empty-query guard:** Skips a pointless request when the input is cleared.
- **Delay choice:** 250–400 ms usually works well for search-as-you-type. Go lower for snappier UX or higher for expensive endpoints.

**Common React mistake:** if you write `const debounced = debounce(fn, 300)` directly in the component body, you get a new debounced function on every render, and the debounce does nothing. Either use the `useDebouncedValue` hook above or keep the debounced function stable with `useMemo`/`useRef` and cancel it on unmount.
